1	//! CUDA Graph state for Qwen3.5 batched decode with bucket padding.
2	
3	use anyhow::Result;
4	use pegainfer_core::cuda_graph::CudaGraphState;
5	use pegainfer_core::tensor::DeviceContext;
6	
7	use super::config::Config35;
8	use super::config::LocalGeometry;
9	use super::decode_buffers::BatchDecodeBuffers35;
10	use super::recurrent_state::LinearStatePointerTables;
11	use super::recurrent_state::RecurrentState;
12	
13	/// Bucket sizes for CUDA Graph capture. Actual batch is padded to nearest bucket.
14	pub(crate) const BATCH_BUCKETS: &[usize] = &[1, 2, 4, 8, 16, 32, 64];
15	
16	/// Maximum supported batch size (= largest bucket).
17	pub(crate) const MAX_BATCH: usize = 64;
18	
19	/// Find the smallest bucket >= `bs`. Panics if `bs` > MAX_BATCH.
20	pub(crate) fn bucket_for(bs: usize) -> usize {
21	    for &b in BATCH_BUCKETS {
22	        if b >= bs {
23	            return b;
24	        }
25	    }
26	    panic!(
27	        "batch size {bs} exceeds largest bucket {}",
28	        BATCH_BUCKETS.last().unwrap()
29	    );
30	}
31	
32	/// CUDA Graph state for Qwen3.5 batch decode.
33	///
34	/// Owns one pre-allocated `RecurrentState` slot per decode-batch capacity
35	/// and shared decode buffers. Slot `i` always maps to position `i` in the batch — when a request
36	/// occupies slot `i`, its recurrent state lives at `slot_states[i]` for the
37	/// entire lifetime of that request in the batch. The CUDA Graph captured for
38	/// a given bucket size always accesses `slot_states[0..bucket_size]`, so GPU
39	/// pointer addresses are identical on every replay.
40	///
41	/// # Slot management
42	///
43	/// Callers must ensure that positions 0..batch_size are active requests and
44	/// positions batch_size..padded_batch_size are padding. When a request
45	/// finishes mid-batch, move the last slot's data to fill the gap:
46	/// ```text
47	/// copy_state_to_slot(ctx, last_slot_src, vacated_slot_idx)
48	/// ```
49	/// and update the caller's slot-to-request mapping accordingly.
50	pub(crate) struct BatchDecodeGraphState {
51	    pub(crate) buffers: BatchDecodeBuffers35,
52	    pub(crate) slot_states: Vec<RecurrentState>,
53	    pub(crate) linear_pointer_tables: LinearStatePointerTables,
54	    /// One `CudaGraphState` per BATCH_BUCKETS entry (indexed by position).
55	    pub(crate) graphs: Vec<CudaGraphState>,
56	}
57	
58	impl BatchDecodeGraphState {
59	    /// Create a graph state at `max_batch` slots (loader-validated bucket).
60	    pub(crate) fn with_capacity(
61	        ctx: &DeviceContext,
62	        config: &Config35,
63	        geometry: LocalGeometry,
64	        page_size: usize,
65	        padding_page_id: i32,
66	        max_batch: usize,
67	    ) -> Result<Self> {
68	        let buffers = BatchDecodeBuffers35::new(
69	            ctx,
70	            config,
71	            geometry,
72	            max_batch,
73	            page_size,
74	            padding_page_id,
75	        )?;
76	
77	        let mut slot_states = Vec::with_capacity(max_batch);
78	        for _ in 0..max_batch {
79	            slot_states.push(RecurrentState::new(ctx, config, geometry)?);
80	        }
81	        let linear_pointer_tables = {
82	            let mut slot_refs: Vec<&mut RecurrentState> = slot_states.iter_mut().collect();
83	            LinearStatePointerTables::from_recurrent_refs(
84	                ctx,
85	                config,
86	                &mut slot_refs,
87	                max_batch,
88	                "Qwen3.5 graph",
89	            )?
90	        };
91	
92	        let graphs = BATCH_BUCKETS
93	            .iter()
94	            .map(|_| CudaGraphState::new())
95	            .collect();
96	
97	        Ok(Self {
98	            buffers,
99	            slot_states,
100	            linear_pointer_tables,
101	            graphs,
102	        })
103	    }
104	
105	    /// D2D copy `src` recurrent state into slot `slot_idx`.
106	    ///
107	    /// Call once when a request joins the batch (after prefill finishes).
108	    /// After this call, `slot_states[slot_idx]` IS the canonical state; the
109	    /// original `src` is no longer used.
110	    pub(crate) fn copy_state_to_slot(
111	        &mut self,
112	        ctx: &DeviceContext,
113	        src: &RecurrentState,
114	        slot_idx: usize,
115	    ) -> Result<()> {
116	        self.slot_states[slot_idx]
117	            .copy_from(ctx, src)
118	            .map_err(|e| anyhow::anyhow!("copy recurrent state to slot {slot_idx}: {e}"))
119	    }
120	
121	    /// D2D move slot `from` into slot `to`, leaving `to` as the canonical
122	    /// state. Used by TP slot compaction when a mid-batch request retires:
123	    /// the last occupied slot moves into the vacated slot so decode rows stay
124	    /// dense (`0..bs`). Slot `from` keeps stale bytes afterwards; admission
125	    /// overwrites it (`copy_state_to_slot`), and padding rows may clobber it —
126	    /// both benign by design.
127	    pub(crate) fn move_slot_within(
128	        &mut self,
129	        ctx: &DeviceContext,
130	        from: usize,
131	        to: usize,
132	    ) -> Result<()> {
133	        anyhow::ensure!(
134	            from != to,
135	            "TP slot compaction move {from} -> {to} is a no-op"
136	        );
137	        anyhow::ensure!(
138	            from < self.slot_states.len() && to < self.slot_states.len(),
139	            "TP slot compaction move {from} -> {to} exceeds {} slots",
140	            self.slot_states.len()
141	        );
142	        let (lo, hi) = (from.min(to), from.max(to));
143	        let (left, right) = self.slot_states.split_at_mut(hi);
144	        let (src, dst) = if from < to {
145	            (&left[from], &mut right[0])
146	        } else {
147	            (&right[0], &mut left[lo])
148	        };
149	        anyhow::ensure!(
150	            src.layers.len() == dst.layers.len(),
151	            "TP slot compaction layer count mismatch: {} vs {}",
152	            src.layers.len(),
153	            dst.layers.len()
154	        );
155	        for (src_layer, dst_layer) in src.layers.iter().zip(dst.layers.iter_mut()) {
156	            ctx.stream
157	                .memcpy_dtod(&src_layer.state, &mut dst_layer.state)
158	                .map_err(|e| anyhow::anyhow!("move recurrent state slot {from} -> {to}: {e}"))?;
159	            ctx.stream
160	                .memcpy_dtod(&src_layer.conv_state.data, &mut dst_layer.conv_state.data)
161	                .map_err(|e| anyhow::anyhow!("move conv state slot {from} -> {to}: {e}"))?;
162	        }
163	        let seq_len = src.seq_len;
164	        let dst = &mut self.slot_states[to];
165	        dst.seq_len = seq_len;
166	        Ok(())
167	    }
168	}
