1	//! Sampling scratch and batched decode buffers for Qwen3.5.
2	
3	use anyhow::Result;
4	use cudarc::driver::CudaSlice;
5	use pegainfer_core::tensor::DeviceContext;
6	use pegainfer_core::tensor::HiddenStates;
7	use pegainfer_kv_cache::KvView;
8	
9	use super::config::Config35;
10	use super::config::LocalGeometry;
11	
12	/// Decode buckets at or below this size read full attention through the split-KV
13	/// kernel instead of the FlashInfer batch-decode kernel.
14	///
15	/// FlashInfer launches one CTA per (request, kv head) and never grows that grid
16	/// with KV length, so a small decode leaves the device idle — four CTAs for a
17	/// single request, 64 for sixteen. Splitting the KV range instead wins at every
18	/// bucket this threshold admits, measured on one tree with two runs a side:
19	/// bs1 9.41/9.36 → 8.57/8.57 ms, c8 11.25/11.27 → 10.65/10.67, c16 13.06/13.08
20	/// → 12.80/12.82 mean TPOT, qps16 unchanged. The wider buckets keep FlashInfer:
21	/// on an sm_90 card at 1024 in and 256 out, routing them through the split form
22	/// measured 10.23/10.25 against 9.65/9.67 ms mean TPOT at c32 and 16.56/16.58
23	/// against 14.98/15.14 at c64. See `docs/models/qwen35/decode-kernel-attribution.md`.
24	pub(crate) const SPLIT_DECODE_MAX_BATCH: usize = 16;
25	
26	/// Query heads per kv head the split-KV kernel is built for, one warp each. A
27	/// checkpoint with another GQA group (the 27B sizes run 6) keeps the FlashInfer
28	/// path at every bucket, since the kernel refuses that geometry.
29	pub(crate) const SPLIT_DECODE_GQA_GROUP: usize = 4;
30	
31	/// KV splits per (kv head, request) CTA group, for a decode bucket.
32	///
33	/// Fixed per bucket rather than derived from KV length because the grid shape
34	/// has to be constant across a captured CUDA Graph bucket; an over-split request
35	/// simply leaves later CTAs empty. The counts are where each bucket's curve
36	/// flattens on the standalone harness: 32 splits is best at batch 1
37	/// (27.98 µs against 34.98 at 16), and 16 is best at batch 8 (57.26 against
38	/// 60.58 at 32) and batch 16 (96.26 against 98.47).
39	pub(crate) fn split_decode_splits(batch: usize) -> usize {
40	    if batch <= 2 { 32 } else { 16 }
41	}
42	
43	/// Upper bound on [`split_decode_splits`], for sizing the partial buffers.
44	pub(crate) const SPLIT_DECODE_MAX_SPLITS: usize = 32;
45	
46	/// Pre-allocated GPU buffers for Qwen3.5 batch decode (N requests, 1 token each).
47	pub(crate) struct BatchDecodeBuffers35 {
48	    pub(crate) max_batch_size: usize,
49	
50	    // Shared hidden-state flow [dim, batch]
51	    pub(crate) hidden: HiddenStates,
52	    pub(crate) normed: HiddenStates,
53	    pub(crate) attn_results: HiddenStates,
54	    pub(crate) hidden_mid: HiddenStates,
55	    pub(crate) gate_up_out: HiddenStates,
56	    pub(crate) act_out: HiddenStates,
57	    pub(crate) mlp_out: HiddenStates,
58	    pub(crate) logits: HiddenStates,
59	
60	    // Full attention [dim, batch]
61	    pub(crate) q_full: HiddenStates,
62	    pub(crate) q_attn: HiddenStates,
63	    pub(crate) k_attn: HiddenStates,
64	    pub(crate) v_attn: HiddenStates,
65	    pub(crate) attn_out_full: HiddenStates,
66	
67	    // Split-KV decode scratch [splits, batch, qo_heads, head_dim] and the two
68	    // per-(split, request, head) softmax accumulators beside it. Sized for the
69	    // buckets the split kernel serves, not for the whole decode capacity.
70	    pub(crate) split_partial_o: CudaSlice<f32>,
71	    pub(crate) split_partial_m: CudaSlice<f32>,
72	    pub(crate) split_partial_l: CudaSlice<f32>,
73	
74	    // Linear attention [dim, batch]. The two projections are the fused ones:
75	    // `qkvz` holds the qkv band below the z band, `ba` holds beta below alpha.
76	    pub(crate) qkvz: HiddenStates,
77	    pub(crate) ba: HiddenStates,
78	    pub(crate) qkv_conv: HiddenStates,
79	    pub(crate) gdr_out: HiddenStates,
80	    pub(crate) normed_gated: HiddenStates,
81	
82	    // Metadata
83	    pub(crate) token_ids_d: CudaSlice<u32>,
84	    pub(crate) positions_d: CudaSlice<i32>,
85	    pub(crate) page_indices_d: CudaSlice<i32>,
86	    pub(crate) page_indptr_d: CudaSlice<i32>,
87	    pub(crate) last_page_len_d: CudaSlice<i32>,
88	    pub(crate) request_indices_d: CudaSlice<i32>,
89	    pub(crate) kv_tile_indices_d: CudaSlice<i32>,
90	    pub(crate) kv_chunk_size_d: CudaSlice<i32>,
91	
92	    // Sampling scratch
93	    pub(crate) sample: pegainfer_sample::SampleScratch,
94	    /// Request-local decode steps handed to `select_batch`, reused across
95	    /// steps to keep the sampling hot path allocation-free. All zeros until
96	    /// the scheduler wires generated counts through (sampling-parity 1b).
97	    pub(crate) steps: Vec<u64>,
98	
99	    /// Page index reserved for CUDA Graph padding slots. Padding entries point
100	    /// here with seq_len=1 so FlashInfer accesses valid (but discarded) memory.
101	    padding_page_id: i32,
102	}
103	
104	impl BatchDecodeBuffers35 {
105	    pub(crate) fn new(
106	        ctx: &DeviceContext,
107	        config: &Config35,
108	        geometry: LocalGeometry,
109	        max_batch_size: usize,
110	        page_size: usize,
111	        padding_page_id: i32,
112	    ) -> Result<Self> {
113	        let h = config.hidden_size;
114	        let bs = max_batch_size;
115	        let max_view_pages = config.max_position_embeddings.div_ceil(page_size).max(1);
116	        let page_index_capacity = bs
117	            .checked_mul(max_view_pages)
118	            .ok_or_else(|| anyhow::anyhow!("Qwen3.5 decode page-index capacity overflow"))?;
119	        let q_proj_dim = geometry.local_full_attn_gated_q_dim();
120	        let q_dim = geometry.local_full_attn_q_dim();
121	        let kv_dim = geometry.local_full_attn_kv_dim();
122	        let qkv_dim = geometry.local_linear_qkv_dim();
123	        let z_dim = geometry.local_linear_z_dim();
124	        let b_dim = geometry.local_linear_num_value_heads();
125	        let intermediate = geometry.local_intermediate_size();
126	
127	        Ok(Self {
128	            max_batch_size: bs,
129	            hidden: HiddenStates::zeros(ctx, h, bs)?,
130	            normed: HiddenStates::zeros(ctx, h, bs)?,
131	            attn_results: HiddenStates::zeros(ctx, h, bs)?,
132	            hidden_mid: HiddenStates::zeros(ctx, h, bs)?,
133	            gate_up_out: HiddenStates::zeros(ctx, 2 * intermediate, bs)?,
134	            act_out: HiddenStates::zeros(ctx, intermediate, bs)?,
135	            mlp_out: HiddenStates::zeros(ctx, h, bs)?,
136	            logits: HiddenStates::zeros(ctx, config.selection_vocab, bs)?,
137	
138	            q_full: HiddenStates::zeros(ctx, q_proj_dim, bs)?,
139	            q_attn: HiddenStates::zeros(ctx, q_dim, bs)?,
140	            k_attn: HiddenStates::zeros(ctx, kv_dim, bs)?,
141	            v_attn: HiddenStates::zeros(ctx, kv_dim, bs)?,
142	            attn_out_full: HiddenStates::zeros(ctx, q_dim, bs)?,
143	
144	            split_partial_o: ctx.stream.alloc_zeros(
145	                SPLIT_DECODE_MAX_SPLITS
146	                    * bs.min(SPLIT_DECODE_MAX_BATCH)
147	                    * geometry.local_num_attention_heads()
148	                    * 256,
149	            )?,
150	            split_partial_m: ctx.stream.alloc_zeros(
151	                SPLIT_DECODE_MAX_SPLITS
152	                    * bs.min(SPLIT_DECODE_MAX_BATCH)
153	                    * geometry.local_num_attention_heads(),
154	            )?,
155	            split_partial_l: ctx.stream.alloc_zeros(
156	                SPLIT_DECODE_MAX_SPLITS
157	                    * bs.min(SPLIT_DECODE_MAX_BATCH)
158	                    * geometry.local_num_attention_heads(),
159	            )?,
160	
161	            qkvz: HiddenStates::zeros(ctx, qkv_dim + z_dim, bs)?,
162	            ba: HiddenStates::zeros(ctx, 2 * b_dim, bs)?,
163	            qkv_conv: HiddenStates::zeros(ctx, qkv_dim, bs)?,
164	            gdr_out: HiddenStates::zeros(ctx, z_dim, bs)?,
165	            normed_gated: HiddenStates::zeros(ctx, z_dim, bs)?,
166	
167	            token_ids_d: ctx.stream.alloc_zeros(bs)?,
168	            positions_d: ctx.stream.alloc_zeros(bs)?,
169	            page_indices_d: ctx.stream.alloc_zeros(page_index_capacity)?,
170	            page_indptr_d: ctx.stream.alloc_zeros(bs + 1)?,
171	            last_page_len_d: ctx.stream.alloc_zeros(bs)?,
172	            request_indices_d: ctx.stream.alloc_zeros(bs)?,
173	            kv_tile_indices_d: ctx.stream.alloc_zeros(bs)?,
174	            kv_chunk_size_d: ctx.stream.alloc_zeros(bs)?,
175	
176	            sample: pegainfer_sample::SampleScratch::with_selection_width(
177	                ctx,
178	                config.selection_vocab,
179	                config.decodable_vocab,
180	                bs,
181	            )?,
182	            steps: Vec::new(),
183	
184	            padding_page_id,
185	        })
186	    }
187	
188	    pub(crate) fn set_batch_size(&mut self, bs: usize) {
189	        assert!(bs <= self.max_batch_size);
190	        self.hidden.seq_len = bs;
191	        self.normed.seq_len = bs;
192	        self.attn_results.seq_len = bs;
193	        self.hidden_mid.seq_len = bs;
194	        self.gate_up_out.seq_len = bs;
195	        self.act_out.seq_len = bs;
196	        self.mlp_out.seq_len = bs;
197	        self.logits.seq_len = bs;
198	
199	        self.q_full.seq_len = bs;
200	        self.q_attn.seq_len = bs;
201	        self.k_attn.seq_len = bs;
202	        self.v_attn.seq_len = bs;
203	        self.attn_out_full.seq_len = bs;
204	
205	        self.qkvz.seq_len = bs;
206	        self.ba.seq_len = bs;
207	        self.qkv_conv.seq_len = bs;
208	        self.gdr_out.seq_len = bs;
209	        self.normed_gated.seq_len = bs;
210	    }
211	
212	    /// Sync paged attention metadata to GPU.
213	    ///
214	    /// `padded_bs` >= `views.len()`: padding slots (if any) point to the
215	    /// reserved padding page with seq_len=1 so FlashInfer accesses valid memory.
216	    pub(crate) fn sync_paged_views(
217	        &mut self,
218	        ctx: &DeviceContext,
219	        views: &[KvView],
220	        padded_bs: usize,
221	    ) -> Result<()> {
222	        let real_bs = views.len();
